head.b:skin:
/*
-----------------------------------------------
Blogger Template Style
Name:        Ophelia
Version:     1.4.0 - Premium
Author:      Templateify
Author Url:  https://www.templateify.com/
----------------------------------------------- */

/*
<!-- Variable definitions -->
<Variable name="keycolor" description="Main Color" type="color" default="#998675" value="#3e551e"/>

<Group description="Theme Widths" selector="body">
  <Variable name="row.width" description="Container Width" type="length" default="1078px" min="960px" max="1078px" value="1078px"/>
  <Variable name="sidebar.width" description="Sidebar Width" type="length" default="300px" min="250px" max="336px" value="300px"/>
</Group>

<Group description="Theme Fonts" selector="body">
<Variable name="main.font" description="Main Site Font" type="font" family="'Work Sans',Arial,sans-serif" default="normal 400 18px $(family)"  value="normal 400 20px Arial, Tahoma, Helvetica, FreeSans, sans-serif"/>
<Variable name="title.font" description="Main Title Font" type="font" family="'Playfair Display',Arial,serif" default="normal 400 18px $(family)"  value="normal normal 24px Cardo"/>
<Variable name="text.font" description="Main Text Font" type="font" family="'Lora',Arial,serif" default="normal 400 14px $(family)"  value="normal 400 20px &#39;Lora&#39;,Arial,serif"/>
</Group>

<Group description="Theme Colors" selector="body">
  <Variable name="main.color" description="Theme Color" type="color" default="#998675" value="#092103"/>
  <Variable name="main.color.two" description="Theme Color 2" type="color" default="#f8efea" value="#092103"/>
  <Variable name="main.dark.color" description="Theme Dark Color" type="color" default="#191919" value="#000000"/>
  <Variable name="title.color" description="Title Color" type="color" default="#111111" value="#000000"/>
  <Variable name="title.hover.color" description="Title Hover Color" type="color" default="$(main.color)" value="#000000"/>
</Group>

<Group description="Theme Body" selector="body">
  <Variable name="body.background.color" description="Body Background - Boxed" type="color" default="#f5f5f5"  value="#f1f1f1"/>
  <Variable name="body.background" description="Background" type="background" color="$(body.background.color)" default="$(color) url() repeat scroll top left" value="#eeeeee url(none) repeat scroll top center"/>
  <Variable name="outer.bg" description="Outer Wrapper Background" type="color" default="#ffffff"  value="#ffffff"/>
  <Variable name="body.text.color" description="Body Text Color" type="color" default="#656565"  value="#494949"/>
  <Variable name="body.link.color" description="Colored Links" type="color" default="$(main.color)"  value="#549d0f"/>
</Group>

<Group description="Main Navbar" selector="div.navbar">
  <Variable name="navbar.bg" description="Navbar Background" type="color" default="$(main.color.two)" value="#092103"/>
  <Variable name="menu.color" description="Menu Color" type="color" default="#111111" value="#FFFFFF"/>
  <Variable name="menu.hover.color" description="Menu Hover Color" type="color" default="#757575" value="#636363"/>
</Group>

<Group description="Sub Menu" selector="div.navbar">
  <Variable name="submenu.bg" description="SubMenu Background" type="color" default="#ffffff" value="#ffffff"/>
  <Variable name="submenu.color" description="SubMenu Color" type="color" default="#757575" value="#636363"/>
  <Variable name="submenu.hover.color" description="SubMenu Hover Color" type="color" default="$(main.color)" value="#3e551e"/>
</Group>

<Group description="Mega Menu" selector="div.navbar">
  <Variable name="megamenu.bg" description="MegaMenu Background" type="color" default="$(submenu.bg)" value="#000000"/>
  <Variable name="megamenu.post.title.color" description="MegaMenu Post Title Color" type="color" default="#111111" value="#000000"/>
  <Variable name="megamenu.post.title.hover" description="MegaMenu Post Title Hover Color" type="color" default="$(title.hover.color)" value="#3e551e"/>
</Group>

<Group description="Blog Posts" select="#main-wrapper">
  <Variable name="post.title.color" description="Post Title Color" type="color" default="$(title.color)" value="#494949"/>
  <Variable name="post.title.hover.color" description="Post Title Hover Color" type="color" default="$(title.hover.color)" value="#494949"/>
  <Variable name="post.text.color" description="Post Text Color" type="color" default="$(body.text.color)" value="#111111"/>
  <Variable name="meta.color" description="Meta Color" type="color" default="#aaa" value="#3e551e"/>
  <Variable name="itempost.title.size" description="ItemPost Title Font Size" type="length" default="33px" min="27px" max="43px" value="35px"/>
  <Variable name="itempost.content.size" description="ItemPost Text Font Size" type="length" default="18px" min="14px" max="20px" value="20px"/>
</Group>

<Group description="Widget Title">
  <Variable name="wtitle.bg" description="Widget Title Background" type="color" default="$(main.color.two)" value="transparent"/>
  <Variable name="wtitle.color" description="Widget Title Color" type="color" default="#111111" value="#000000"/>
</Group>

<Group description="Theme Buttons">
  <Variable name="button.bg" description="Button Background" type="color" default="$(main.color)" value="#073110"/>
  <Variable name="button.color" description="Button Color" type="color" default="#ffffff" value="#f1f1f1"/>
  <Variable name="button.hover.bg" description="Button Hover Background" type="color" default="$(main.dark.color)" value="#092514"/>
  <Variable name="button.hover.color" description="Button Hover Color" type="color" default="#ffffff" value="#ffffff"/>
</Group>

<Group description="Theme Footer" selector="div.footer-widgets-wrap">
  <Variable name="footer.bg" description="Footer Background" type="color" default="$(main.dark.color)" value="#000000"/>
  <Variable name="footer.widget.title.color" description="Widget Title Color" type="color" default="#f2f2f2" value="#eeeeee"/>
  <Variable name="footer.color" description="Footer Color" type="color" default="#f2f2f2" value="#eeeeee"/>
  <Variable name="footer.hover.color" description="Footer Links Hover Color" type="color" default="#a5a5a5" value="#9d9d9d"/>
  <Variable name="footer.post.title.hover.color" description="Footer Post Title Hover Color" type="color" default="#a5a5a5" value="#9d9d9d"/>
  <Variable name="footer.text.color" description="Footer Text Color" type="color" default="#aaaaaa" value="#a2a2a2"/>
</Group>

<!-- Main Site Font -->
<Variable name="mainfont.medium" description="Main Font Medium" hideEditor="true" type="font" default="normal 500 18px $(main.font.family)" value="normal 500 18px $(family)"/>
<Variable name="mainfont.semibold" description="Main Font SemiBold" hideEditor="true" type="font" default="normal 600 18px $(main.font.family)" value="normal 600 18px $(family)"/>
<Variable name="mainfont.bold" description="Main Font Bold" hideEditor="true" type="font" default="normal 700 18px $(main.font.family)" value="normal 700 18px $(family)"/>
<Variable name="mainfont.italic" description="Main Font Italic" hideEditor="true" type="font" default="italic 500 18px $(main.font.family)" value="italic 500 18x $(family)"/>
<Variable name="mainfont.mediumitalic" description="Main Font Medium Italic" hideEditor="true" type="font" default="italic 500 14px $(main.font.family)" value="italic 500 18px $(family)"/>
<Variable name="mainfont.semibolditalic" description="Main Font SemiBold Italic" hideEditor="true" type="font" default="italic 600 14px $(main.font.family)" value="italic 600 14px $(family)"/>
<Variable name="mainfont.bolditalic" description="Main Font Bold Italic" hideEditor="true" type="font" default="italic 700 14px $(main.font.family)" value="italic 700 14px $(family)"/>

<!-- Main Title Font -->
<Variable name="titlefont.medium" description="Title Font Medium" hideEditor="true" type="font" default="normal 500 14px $(title.font.family)" value="normal 500 14px $(family)"/>
<Variable name="titlefont.semibold" description="Title Font SemiBold" hideEditor="true" type="font" default="normal 600 14px $(title.font.family)" value="normal 600 14px $(family)"/>
<Variable name="titlefont.bold" description="Title Font Bold" hideEditor="true" type="font" default="normal 700 14px $(title.font.family)" value="normal 700 14px $(family)"/>
<Variable name="titlefont.italic" description="Title Font Italic" hideEditor="true" type="font" default="italic 500 14px $(title.font.family)" value="italic 500 14px $(family)"/>
<Variable name="titlefont.mediumitalic" description="Title Font Medium Italic" hideEditor="true" type="font" default="italic 500 14px $(title.font.family)" value="italic 500 14px $(family)"/>
<Variable name="titlefont.semibolditalic" description="Title Font SemiBold Italic" hideEditor="true" type="font" default="italic 600 14px $(title.font.family)" value="italic 600 14px $(family)"/>
<Variable name="titlefont.bolditalic" description="Title Font Bold Italic" hideEditor="true" type="font" default="italic 700 14px $(title.font.family)" value="italic 700 14px $(family)"/>

<!-- Main Text Font -->
<Variable name="textfont.medium" description="Text Font Medium" hideEditor="true" type="font" default="normal 500 18px $(text.font.family)" value="normal 500 18px $(family)"/>
<Variable name="textfont.semibold" description="Text Font SemiBold" hideEditor="true" type="font" default="normal 600 14px $(text.font.family)" value="normal 600 14px $(family)"/>
<Variable name="textfont.bold" description="Text Font Bold" hideEditor="true" type="font" default="normal 700 14px $(text.font.family)" value="normal 700 14px $(family)"/>
<Variable name="textfont.italic" description="Text Font Italic" hideEditor="true" type="font" default="italic 500 14px $(text.font.family)" value="italic 500 14px $(family)"/>
<Variable name="textfont.mediumitalic" description="Text Font Medium Italic" hideEditor="true" type="font" default="italic 500 14px $(text.font.family)" value="italic 500 14px $(family)"/>
<Variable name="textfont.semibolditalic" description="Text Font SemiBold Italic" hideEditor="true" type="font" default="italic 600 14px $(text.font.family)" value="italic 600 14px $(family)"/>
<Variable name="textfont.bolditalic" description="Text Font Bold Italic" hideEditor="true" type="font" default="italic 700 14px $(text.font.family)" value="italic 700 14px $(family)"/>

<!-- Comments Default -->
<Variable name="body.text.font" description="Font" hideEditor="true" type="font" default="14px 'Lato', sans-serif"  value="14px &#39;Lato&#39;, sans-serif"/>
<Variable name="tabs.font" description="Font 2" hideEditor="true" type="font" default="14px 'Lato', sans-serif"  value="14px &#39;Lato&#39;, sans-serif"/>
<Variable name="posts.background.color" description="Post Background" hideEditor="true" type="color" default="$(outer.bg)"  value="#ffffff"/>
<Variable name="posts.title.color" description="Post title color" hideEditor="true" type="color" default="$(post.title.color)"  value="#111111"/>
<Variable name="posts.text.color" description="Post text color" hideEditor="true" type="color" default="$(post.text.color)"  value="#656565"/>
<Variable name="posts.icons.color" description="Post icons color" hideEditor="true" type="color" default="$(main.color)"  value="#998675"/>
<Variable name="labels.background.color" description="Label background color" hideEditor="true" type="color" default="$(main.color)"  value="#998675"/>
*/

/*-- Work Sans Font --*/
@font-face{font-family:'Work Sans';font-style:normal;font-weight:400;src:local('Work Sans'),local(WorkSans-Regular),url(https://fonts.gstatic.com/s/worksans/v4/QGYsz_wNahGAdqQ43Rh_cqDpp_k.woff2) format("woff2");unicode-range:U+0100-024F,U+0259,U+1E00-1EFF,U+2020,U+20A0-20AB,U+20AD-20CF,U+2113,U+2C60-2C7F,U+A720-A7FF}
