/*-- Reset CSS --*/
a,abbr,acronym,address,applet,b,big,blockquote,body,caption,center,cite,code,dd,del,dfn,div,dl,dt,em,fieldset,font,form,h1,h2,h3,h4,h5,h6,html,i,iframe,img,ins,kbd,label,legend,li,object,p,pre,q,s,samp,small,span,strike,strong,sub,sup,table,tbody,td,tfoot,th,thead,tr,tt,u,ul,var{padding:0;border:0;outline:0;vertical-align:baseline;background:0 0;text-decoration:none}form,textarea,input,button{-webkit-appearance:none;-moz-appearance:none;appearance:none;outline:none;border-radius:0}dl,ul{list-style-position:inside;font-weight:400;list-style:none}ul li{list-style:none}caption,th{text-align:center}img{border:none;position:relative}a,a:visited{text-decoration:none}.clearfix{clear:both}.section,.widget,.widget ul{margin:0;padding:0}a{color:$(body.link.color)}a img{border:0}abbr{text-decoration:none}.CSS_LIGHTBOX{z-index:999999!important}.separator a{clear:none!important;float:none!important;margin-left:0!important;margin-right:0!important}#navbar-iframe,.widget-item-control,a.quickedit,.home-link,.feed-links{display:none!important}.center{display:table;margin:0 auto;position:relative}.widget > h2,.widget > h3{display:none}.widget iframe,.widget img{max-width:100%}

/*-- Body Content CSS --*/
:root{--body-font:$(main.font.family);--title-font:$(title.font.family);--text-font:$(text.font.family)}
body{position:relative;background-color:$(body.background.color);background:$(body.background);font-family:var(--body-font);font-size:18px;color:$(body.text.color);font-weight:400;font-style:normal;line-height:1.4em;word-wrap:break-word;margin:0;padding:0}
.rtl{direction:rtl}
.no-items.section{display:none}
h1,h2,h3,h4,h5,h6{font-family:var(--title-font);font-weight:700}
#outer-wrapper{position:relative;overflow:hidden;width:100%;max-width:100%;margin:0 auto;background-color:$(outer.bg);box-shadow:0 0 20px rgba(0,0,0,0.1)}
.row-x1{width:$(row.width)}
#content-wrapper{position:relative;float:left;width:100%;padding:50px 0}
#content-wrapper > .container{margin:0 auto}
#main-wrapper{float:left;overflow:hidden;width:calc(100% - ($(sidebar.width) + 50px));box-sizing:border-box;padding:0}
.rtl #main-wrapper{float:right}
#sidebar-wrapper{float:right;overflow:hidden;width:$(sidebar.width);box-sizing:border-box;padding:0}
.rtl #sidebar-wrapper{float:left}
.entry-image-link,.cmm-avatar,.comments .avatar-image-container{background-color:rgba(155,155,155,0.08);color:transparent!important}
.entry-thumb{display:block;position:relative;width:100%;height:100%;background-size:cover;background-position:center center;background-repeat:no-repeat;z-index:1;opacity:0;transition:opacity .25s ease, filter 0s ease}
.entry-thumb.lazy-ify{opacity:1}
.entry-image-link:hover .entry-thumb,.slider-item-inner:hover .entry-image-link .entry-thumb{filter:brightness(1.07)}
.before-mask:before{content:'';position:absolute;left:0;right:0;bottom:0;height:65%;background-image:linear-gradient(to bottom,transparent,rgba(0,0,0,0.65));-webkit-backface-visibility:hidden;backface-visibility:hidden;z-index:2;opacity:1;margin:-1px;transition:opacity .25s ease}
.entry-title{color:$(post.title.color)}
.entry-title a{color:$(post.title.color)}
.entry-title a:hover{color:$(post.title.hover.color);border-bottom:1px solid}
.excerpt{font-family:var(--text-font)}
.social a:before{display:inline-block;font-family:'Font Awesome 5 Brands';font-style:normal;font-weight:400}
.social .blogger a:before{content:"\f37d"}
.social .facebook a:before{content:"\f09a"}
.social .facebook-f a:before{content:"\f39e"}
.social .twitter a:before{content:"\f099"}
.social .rss a:before{content:"\f09e";font-family:'Font Awesome 5 Free';font-weight:900}
.social .youtube a:before{content:"\f167"}
.social .skype a:before{content:"\f17e"}
.social .stumbleupon a:before{content:"\f1a4"}
.social .tumblr a:before{content:"\f173"}
.social .vk a:before{content:"\f189"}
.social .stack-overflow a:before{content:"\f16c"}
.social .github a:before{content:"\f09b"}
.social .linkedin a:before{content:"\f0e1"}
.social .dribbble a:before{content:"\f17d"}
.social .soundcloud a:before{content:"\f1be"}
.social .behance a:before{content:"\f1b4"}
.social .digg a:before{content:"\f1a6"}
.social .instagram a:before{content:"\f16d"}
.social .pinterest a:before{content:"\f0d2"}
.social .pinterest-p a:before{content:"\f231"}
.social .twitch a:before{content:"\f1e8"}
.social .delicious a:before{content:"\f1a5"}
.social .codepen a:before{content:"\f1cb"}
.social .flipboard a:before{content:"\f44d"}
.social .reddit a:before{content:"\f281"}
.social .whatsapp a:before{content:"\f232"}
.social .messenger a:before{content:"\f39f"}
.social .snapchat a:before{content:"\f2ac"}
.social .telegram a:before{content:"\f3fe"}
.social .email a:before{content:"\f0e0";font-family:'Font Awesome 5 Free';font-weight:400}
.social .external-link a:before{content:"\f35d";font-family:'Font Awesome 5 Free';font-weight:900}
.social-color .blogger a,.social-hover-color .blogger a:hover{background-color:#ff5722}
.social-color .facebook a,.social-color .facebook-f a,.social-hover-color .facebook a:hover,.social-hover-color .facebook-f a:hover{background-color:#3b5999}
.social-color .twitter a,.social-hover-color .twitter a:hover{background-color:#00acee}
.social-color .youtube a,.social-hover-color .youtube a:hover{background-color:#f50000}
.social-color .instagram a,.social-hover-color .instagram a:hover{background:linear-gradient(15deg,#ffb13d,#dd277b,#4d5ed4)}
.social-color .pinterest a,.social-color .pinterest-p a,.social-hover-color .pinterest a:hover,.social-hover-color .pinterest-p a:hover{background-color:#ca2127}
.social-color .dribbble a,.social-hover-color .dribbble a:hover{background-color:#ea4c89}
.social-color .linkedin a,.social-hover-color .linkedin a:hover{background-color:#0077b5}
.social-color .tumblr a,.social-hover-color .tumblr a:hover{background-color:#365069}
.social-color .twitch a,.social-hover-color .twitch a:hover{background-color:#6441a5}
.social-color .rss a,.social-hover-color .rss a:hover{background-color:#ffc200}
.social-color .skype a,.social-hover-color .skype a:hover{background-color:#00aff0}
.social-color .stumbleupon a,.social-hover-color .stumbleupon a:hover{background-color:#eb4823}
.social-color .vk a,.social-hover-color .vk a:hover{background-color:#4a76a8}
.social-color .stack-overflow a,.social-hover-color .stack-overflow a:hover{background-color:#f48024}
.social-color .github a,.social-hover-color .github a:hover{background-color:#24292e}
.social-color .soundcloud a,.social-hover-color .soundcloud a:hover{background:linear-gradient(#ff7400,#ff3400)}
.social-color .behance a,.social-hover-color .behance a:hover{background-color:#191919}
.social-color .digg a,.social-hover-color .digg a:hover{background-color:#1b1a19}
.social-color .delicious a,.social-hover-color .delicious a:hover{background-color:#0076e8}
.social-color .codepen a,.social-hover-color .codepen a:hover{background-color:#000}
.social-color .flipboard a,.social-hover-color .flipboard a:hover{background-color:#f52828}
.social-color .reddit a,.social-hover-color .reddit a:hover{background-color:#ff4500}
.social-color .whatsapp a,.social-hover-color .whatsapp a:hover{background-color:#3fbb50}
.social-color .messenger a,.social-hover-color .messenger a:hover{background-color:#0084ff}
.social-color .snapchat a,.social-hover-color .snapchat a:hover{background-color:#ffe700}
.social-color .telegram a,.social-hover-color .telegram a:hover{background-color:#179cde}
.social-color .email a,.social-hover-color .email a:hover{background-color:#888}
.social-color .external-link a,.social-hover-color .external-link a:hover{background-color:$(button.hover.bg)}
#header-wrapper{position:relative;float:left;width:100%;margin:0;border-bottom:1px solid rgba(155,155,155,0.15)}
.home #header-wrapper.has-featured{border:0}
#header-wrapper .container{position:relative;margin:0 auto}
.main-logo-wrap{position:relative;float:left;width:100%;text-align:center;margin:0}
.main-logo{position:relative;float:left;width:100%;height:100px;padding:40px 0;margin:0}
.header-widget{display:inline-block}
.main-logo .main-logo-img{float:left;height:100px;overflow:hidden}
.main-logo img{max-width:100%;height:100px;margin:0}
.main-logo h1{display:block;font-size:53px;color:$(title.color);font-weight:600;font-style:italic;line-height:100px;margin:0}
.main-logo h1 a{display:inline-block;color:$(title.color)}
.main-logo h1 a:hover{color:$(title.hover.color)}
.main-logo #h1-tag{position:absolute;top:-9000px;left:-9000px;display:none;visibility:hidden}
.navbar-wrap,.navbar{position:relative;float:left;width:100%;height:54px;background-color:$(navbar.bg);padding:0;margin:0;border-bottom:0 solid rgba(155,155,155,0.15)}
.navbar{border:0}
.menu-wrap{position:static;float:left;height:54px;margin:0}
.rtl .menu-wrap{float:right}
#ophelia-pro-main-menu .widget,#ophelia-pro-main-menu .widget > .widget-title{display:none}
#ophelia-pro-main-menu .show-menu{display:block}
#ophelia-pro-main-menu{position:static;width:100%;height:54px;z-index:10}
#ophelia-pro-main-menu ul > li{position:relative;float:left;display:inline-block;padding:0;margin:0}
.rtl #ophelia-pro-main-menu ul > li{float:right}
#ophelia-pro-main-menu-nav > li > a{position:relative;display:block;height:54px;font-size:11px;color:$(menu.color);font-weight:500;text-transform:uppercase;line-height:54px;padding:0 20px;margin:0}
#ophelia-pro-main-menu-nav > li:first-child > a{padding:0 20px 0 0}
.rtl #ophelia-pro-main-menu-nav > li:first-child > a{padding:0 0 0 20px}
#ophelia-pro-main-menu-nav > li:hover > a{color:$(menu.hover.color)}
#ophelia-pro-main-menu ul > li > ul{position:absolute;float:left;left:0;top:54px;width:190px;background-color:$(submenu.bg);z-index:99999;visibility:hidden;opacity:0;padding:0;margin:-1px 0 0;border:1px solid rgba(155,155,155,0.1);box-shadow:0 4px 7px rgba(190,190,190,0.08)}
#ophelia-pro-main-menu ul > li > ul > li:last-child a{border:0}
.rtl #ophelia-pro-main-menu ul > li > ul{left:auto;right:0}
#ophelia-pro-main-menu ul > li > ul > li > ul{position:absolute;float:left;top:0;left:100%;margin:-1px 0 0}
.rtl #ophelia-pro-main-menu ul > li > ul > li > ul{float:left;left:auto;right:100%}
#ophelia-pro-main-menu ul > li > ul > li{display:block;float:none;position:relative}
.rtl #ophelia-pro-main-menu ul > li > ul > li{float:none}
#ophelia-pro-main-menu ul > li > ul > li a{position:relative;display:block;height:36px;font-size:11px;color:$(submenu.color);line-height:36px;font-weight:500;text-transform:uppercase;box-sizing:border-box;padding:0 20px;margin:0;border-bottom:1px solid rgba(155,155,155,0.1)}
#ophelia-pro-main-menu ul > li > ul > li:hover > a{color:$(submenu.hover.color)}
#ophelia-pro-main-menu ul > li.has-sub > a:after{content:'\f078';float:right;font-family:'Font Awesome 5 Free';font-size:9px;color:$(menu.color);font-weight:900;opacity:.65;margin:0 0 0 6px}
.rtl #ophelia-pro-main-menu ul > li.has-sub > a:after{float:left;margin:-1px 5px 0 0}
#ophelia-pro-main-menu ul > li > ul > li.has-sub > a:after{content:'\f054';float:right;color:$(submenu.color);margin:0}
.rtl #ophelia-pro-main-menu ul > li > ul > li.has-sub > a:after{content:'\f053'}
#ophelia-pro-main-menu ul > li:hover > ul,#ophelia-pro-main-menu ul > li > ul > li:hover > ul{visibility:visible;opacity:1}
#ophelia-pro-main-menu ul ul{transition:all .17s ease}
#ophelia-pro-main-menu .getMega{display:none}
#ophelia-pro-main-menu .mega-menu{position:static!important}
#ophelia-pro-main-menu .mega-menu > ul{width:100%;background-color:$(megamenu.bg);box-sizing:border-box;padding:20px 10px}
#ophelia-pro-main-menu .mega-menu > ul.mega-widget{overflow:hidden}
.mega-widget .mega-item{float:left;width:25%;box-sizing:border-box;padding:0 10px}
.rtl .mega-widget .mega-item{float:right}
.mega-widget .mega-content{position:relative;width:100%;overflow:hidden;padding:0}
.mega-content .entry-image-link{width:100%;height:150px;background-color:rgba(255,255,255,0.01);z-index:1;display:block;position:relative;overflow:hidden;padding:0}
.mega-content .entry-title{position:relative;font-size:14px;font-weight:600;line-height:1.3em;margin:8px 0 2px;padding:0}
.mega-content .entry-title a{color:$(megamenu.post.title.color)}
.mega-content .entry-title a:hover{color:$(megamenu.post.title.hover)}
.no-posts{display:block;font-size:14px;color:$(title.color);padding:35px 0;font-weight:400}
.mega-menu .no-posts{color:$(meta.color);text-align:center;padding:0}
.social-wrap{position:absolute;top:0;right:64px;height:40px;z-index:20;margin:7px 0 0}
.rtl .social-wrap{right:auto;left:64px}
#main-social .widget > .widget-title{display:none}
.main-social ul{float:right;margin:0}
.main-social ul li{position:relative;float:left;margin:0}
.rtl .main-social ul li{float:right}
.main-social ul li a{float:left;width:26px;height:40px;font-size:18px;color:$(menu.color);line-height:40px;text-align:center;margin:0 0 0 5px}
.rtl .main-social ul li a{float:right}
.main-social ul li a:hover{color:$(menu.hover.color)}
.show-search,.hide-search{position:absolute;top:0;right:0;display:block;width:54px;height:54px;background-color:rgba(155,155,155,0.07);color:$(menu.color);font-size:20px;line-height:54px;text-align:center;cursor:pointer;z-index:20;padding:0;margin:0}
.rtl .show-search,.rtl .hide-search{right:auto;left:0}
.show-search:before{content:"\f002";font-family:'Font Awesome 5 Free';font-weight:900}
.hide-search:before{content:"\f00d";font-family:'Font Awesome 5 Free';font-weight:900}
.show-search:hover,.hide-search:hover{color:$(menu.hover.color)}
#nav-search{display:none;position:absolute;left:0;top:0;width:100%;height:54px;z-index:25;background-color:$(navbar.bg);box-sizing:border-box;padding:0}
#nav-search .search-form{width:100%;height:54px;background-color:rgba(0,0,0,0);line-height:54px;overflow:hidden;padding:0}
#nav-search .search-input{width:100%;height:54px;color:$(menu.color);margin:0;padding:0 54px 0 0;background-color:rgba(0,0,0,0);font-family:inherit;font-size:18px;font-weight:400;box-sizing:border-box;border:0}
.rtl #nav-search .search-input{padding:0 0 0 54px}
#nav-search .search-input:focus{color:$(menu.color);outline:none}
#nav-search .search-input::placeholder{color:$(menu.color);opacity:.5}
.overlay{visibility:hidden;opacity:0;position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,.7);z-index:1000;-webkit-backdrop-filter:saturate(100%) blur(2px);-ms-backdrop-filter:saturate(100%) blur(2px);-o-backdrop-filter:saturate(100%) blur(2px);backdrop-filter:saturate(100%) blur(2px);margin:0;transition:all .25s ease}
.show-mobile-menu{display:none;position:absolute;top:0;left:0;height:54px;color:$(menu.color);font-size:20px;font-weight:500;text-align:center;text-transform:uppercase;line-height:54px;cursor:pointer;z-index:20;padding:0 20px}
.rtl .show-mobile-menu{left:auto;right:0}
