#slide-menu{display:none;position:fixed;width:300px;height:100%;top:0;left:-100%;bottom:0;background-color:$(outer.bg);overflow:auto;z-index:1010;visibility:hidden;box-shadow:3px 0 7px rgba(0,0,0,0.1);transition:all .25s ease}
.rtl #slide-menu{left:unset;right:-100%}
