.mobile-logo img{max-width:100%;height:34px}
.hide-mobile-menu{position:absolute;top:0;right:0;display:block;height:54px;color:$(title.color);font-size:16px;line-height:54px;text-align:center;cursor:pointer;z-index:20;padding:0 20px}
.rtl .hide-mobile-menu{right:auto;left:0}
.hide-mobile-menu:before{content:"\f00d";font-family:'Font Awesome 5 Free';font-weight:900}
.hide-mobile-menu:hover{color:$(title.hover.color)}
.slide-menu-flex{display:flex;flex-direction:column;justify-content:space-between;float:left;width:100%;height:calc(100% - 54px)}
.mobile-menu{position:relative;float:left;width:100%;box-sizing:border-box;padding:20px}
.mobile-menu > ul{margin:0}
.mobile-menu .m-sub{display:none;padding:0}
.mobile-menu ul li{position:relative;display:block;overflow:hidden;float:left;width:100%;font-size:16px;font-weight:500;text-transform:uppercase;line-height:40px;margin:0;padding:0}
.mobile-menu > ul li ul{overflow:hidden}
