.mobile-menu ul li.has-sub .submenu-toggle{position:absolute;top:0;right:0;color:$(title.color);cursor:pointer}
.rtl .mobile-menu ul li.has-sub .submenu-toggle{right:auto;left:0}
.mobile-menu ul li.has-sub .submenu-toggle:after{content:'\f078';font-family:'Font Awesome 5 Free';font-weight:900;float:right;width:40px;font-size:16px;text-align:right;transition:all .17s ease}
.rtl .mobile-menu ul li.has-sub .submenu-toggle:after{text-align:left}
.mobile-menu ul li.has-sub.show > .submenu-toggle:after{content:'\f077'}
.mobile-menu ul li a:hover,.mobile-menu ul li.has-sub.show > a,.mobile-menu ul li.has-sub.show > .submenu-toggle{color:$(title.hover.color)}
.mobile-menu > ul > li > ul > li a{font-size:16px;font-weight:500;opacity:.9;padding:0 0 0 15px}
.rtl .mobile-menu > ul > li > ul > li a{padding:0 15px 0 0}
.mobile-menu > ul > li > ul > li > ul > li > a{padding:0 0 0 30px}
.rtl .mobile-menu > ul > li > ul > li > ul > li > a{padding:0 30px 0 0}
