.related-posts .entry-image-link{position:relative;display:block;width:100%;height:140px;margin:0}
.related-posts .entry-title{font-size:15px;font-weight:600;line-height:1.3em;display:block;margin:8px 0 3px}
.about-author{position:relative;float:left;width:100%;box-sizing:border-box;padding:20px;margin:40px 0 0;border:1px solid rgba(155,155,155,0.15)}
.about-author .avatar-container{position:relative;float:left;width:60px;height:60px;background-color:rgba(155,155,155,0.1);overflow:hidden;margin:0 17px 0 0;border-radius:100%}
.rtl .about-author .avatar-container{float:right;margin:0 0 0 17px}
.about-author .author-avatar{float:left;width:100%;height:100%;background-size:100% 100%;background-position:0 0;background-repeat:no-repeat;opacity:0;overflow:hidden;border-radius:100%;transition:opacity .25s ease}
.about-author .author-avatar.lazy-ify{opacity:1}
.about-author .author-name{display:block;font-size:19px;color:$(title.color);font-weight:700;margin:0 0 12px}
.about-author .author-name a{color:$(title.color)}
.about-author .author-name a:hover{color:$(title.hover.color);text-decoration:none}
.author-description{overflow:hidden}
.author-description span{display:block;overflow:hidden;font-size:14px;color:$(body.text.color);font-weight:400;line-height:1.6em}
.author-description span br{display:none}
.author-description a{display:none;float:left;font-size:14px;color:$(title.color);text-align:center;padding:0;margin:12px 13px 0 0}
.rtl .author-description a{float:right;margin:12px 0 0 13px}
.author-description a:hover{color:$(title.hover.color)}
.author-description.show-icons li,.author-description.show-icons a{display:inline-block}
.post-nav{position:relative;float:left;width:100%;overflow:hidden;font-size:13px;box-sizing:border-box;margin:40px 0 0}
.post-nav a{color:$(meta.color)}
.post-nav a:hover{color:$(title.hover.color)}
.post-nav span{color:$(meta.color);opacity:.8}
.post-nav .blog-pager-newer-link:before,.post-nav .blog-pager-older-link:after{margin-top:1px}
.post-nav .blog-pager-newer-link,.rtl .post-nav .blog-pager-older-link{float:left}
.post-nav .blog-pager-older-link,.rtl .post-nav .blog-pager-newer-link{float:right}
.post-nav .blog-pager-newer-link:before,.rtl .post-nav .blog-pager-older-link:after{content:'\f053';float:left;font-family:'Font Awesome 5 Free';font-size:9px;font-weight:900;margin:0 4px 0 0}
.post-nav .blog-pager-older-link:after,.rtl .post-nav .blog-pager-newer-link:before{content:'\f054';float:right;font-family:'Font Awesome 5 Free';font-size:9px;font-weight:900;margin:0 0 0 4px}
#blog-pager{float:left;width:100%;font-size:15px;font-weight:500;text-align:center;clear:both;box-sizing:border-box;padding:0;margin:60px 0 10px}
#blog-pager .load-more{display:inline-block;height:36px;font-size:12px;color:$(meta.color);font-weight:500;text-transform:uppercase;line-height:36px;padding:0 25px;margin:0}
#blog-pager #load-more-link{background-color:rgba(155,155,155,0.1);color:$(meta.color);cursor:pointer}
#blog-pager #load-more-link:hover{background-color:$(button.hover.bg);color:$(button.hover.color)}
#blog-pager .load-more.no-more{background-color:rgba(155,155,155,0.1);color:$(title.color)}
#blog-pager .loading,#blog-pager .no-more{display:none}
#blog-pager .loading .loader{height:36px}
#blog-pager .no-more.show{display:inline-block}
#blog-pager .loading .loader:after{width:26px;height:26px;margin:-15px 0 0 -15px}
.ophelia-pro-blog-post-comments{display:none;float:left;width:100%;box-sizing:border-box;padding:0;margin:0}
#comments,#disqus_thread{float:left;width:100%}
.ophelia-pro-blog-post-comments .fb_iframe_widget_fluid_desktop,.ophelia-pro-blog-post-comments .fb_iframe_widget_fluid_desktop span,.ophelia-pro-blog-post-comments .fb_iframe_widget_fluid_desktop iframe{float:left;display:block!important;width:100%!important}
.comments-system-facebook{width:calc(100% + 16px);margin-left:-8px}
.fb-comments{padding:0;margin:40px 0 0}
.comments{display:block;clear:both;padding:0;margin:40px 0 0}
.comments-system-disqus .comments{margin:25px 0 0}
.comments-title.has-message{margin:0 0 20px}
.comments .comments-content{float:left;width:100%;margin:0}
#comments h4#comment-post-message{display:none}
.comments .comment-block{padding:20px 0 0 50px;border-top:1px solid rgba(155,155,155,0.15)}
.rtl .comments .comment-block{padding:20px 50px 0 0}
.comments .comment-content{font-family:var(--text-font);font-size:14px;color:$(body.text.color);line-height:1.6em;margin:10px 0 15px}
.comments .comment-content > a:hover{text-decoration:underline}
.comment-thread .comment{position:relative;padding:0;margin:25px 0 0;list-style:none;border-radius:0}
.comment-thread ol{padding:0;margin:0}
.toplevel-thread ol > li:first-child{margin:0}
.toplevel-thread ol > li:first-child > .comment-block{padding-top:0;margin:0;border:0}
.comment-thread.toplevel-thread > ol > .comment > .comment-replybox-single iframe{box-sizing:border-box;padding:0 0 0 50px;margin:15px 0 0}
.comment-thread ol ol .comment:before{content:'\f3bf';position:absolute;left:-25px;top:-10px;font-family:'Font Awesome 5 Free';font-size:16px;color:rgba(155,155,155,0.15);font-weight:700;transform:rotate(90deg);margin:0}
.comment-thread .avatar-image-container{position:absolute;top:20px;left:0;width:35px;height:35px;border-radius:100%;overflow:hidden}
.toplevel-thread ol > li:first-child > .avatar-image-container{top:0}
.rtl .comment-thread .avatar-image-container{left:auto;right:0}
.avatar-image-container img{width:100%;height:100%;border-radius:100%}
.comments .comment-header .user{font-family:var(--title-font);font-size:16px;color:$(title.color);display:inline-block;font-style:normal;font-weight:700;margin:0 0 3px}
.comments .comment-header .user a{color:$(title.color)}
.comments .comment-header .user a:hover{color:$(title.hover.color)}
.comments .comment-header .icon.user{display:none}
.comments .comment-header .icon.blog-author{display:inline-block;font-size:12px;color:$(main.color);font-weight:400;vertical-align:top;margin:-3px 0 0 5px}
.rtl .comments .comment-header .icon.blog-author{margin:-3px 5px 0 0}
.comments .comment-header .icon.blog-author:before{content:'\f058';font-family:'Font Awesome 5 Free';font-weight:400}
.comments .comment-header .datetime{display:inline-block;margin:0 0 0 10px}
.rtl .comments .comment-header .datetime{margin:0 10px 0 0}
.comment-header .datetime a{font-size:11px;color:$(meta.color);padding:0}
.comments .comment-actions{display:block;margin:0}
.comments .comment-actions a{display:inline-block;height:16px;font-size:11px;color:$(meta.color);font-style:normal;line-height:15px;padding:0 7px;margin:0 12px 0 0;border:1px solid rgba(155,155,155,0.15);border-radius:2px;box-shadow:0 1px 1px 0 rgba(155,155,155,0.05)}
.rtl .comments .comment-actions a{margin:0 0 0 12px}
.comments .comment-actions a:hover{color:$(title.hover.color)}
.item-control{display:none}
.loadmore.loaded a{display:inline-block;border-bottom:1px solid rgba(155,155,155,.51);text-decoration:none;margin-top:15px}
.comments .continue{display:none}
.comments .toplevel-thread > #top-continue a{display:block;color:$(body.link.color);text-align:center;margin:35px 0 0}
.comments .toplevel-thread > #top-continue a:hover{color:$(title.color)}
.comments .comment-replies{padding:0 0 0 50px}
.thread-expanded .thread-count a,.loadmore{display:none}
.comments .footer,.comments .comment-footer{float:left;width:100%;font-size:13px;margin:0}
.comments .comment-thread > .comment-replybox-thread{margin:40px 0 0}
.comment-form{float:left;width:100%;margin:0}
p.comments-message{float:left;width:100%;font-size:14px;color:$(meta.color);font-style:italic;padding:5px 0 25px;margin:0}
.no-comments p.comments-message{padding:0 0 20px}
p.comments-message > a{color:$(body.link.color)}
p.comments-message > a:hover{text-decoration:underline}
p.comments-message > em{color:#d63031;font-style:normal}
.comment-form > p{display:none}
p.comment-footer span{color:$(meta.color)}
p.comment-footer span:after{content:'\002A';color:#d63031}
iframe#comment-editor{min-height:93px}
#sidebar-wrapper .sidebar{float:left;width:100%}
.sidebar > .widget{position:relative;float:left;width:100%;box-sizing:border-box;padding:0;margin:0 0 50px}
#sidebar > .widget:last-child{margin:0}
.sidebar .widget > .widget-title{position:relative;float:left;width:100%;height:36px;background-color:$(wtitle.bg);display:block;margin:0 0 25px}
.sidebar .widget > .widget-title > h3{position:relative;float:left;width:100%;height:36px;font-family:var(--body-font);font-size:12px;color:$(wtitle.color);font-weight:500;text-align:center;text-transform:uppercase;line-height:36px;padding:0;margin:0}
.sidebar .widget-content{float:left;width:100%;box-sizing:border-box;padding:0}
.sidebar .loader{height:180px}
.custom-widget .custom-item{display:block;overflow:hidden;padding:0;margin:25px 0 0}
.custom-widget .custom-item.item-0{margin:0}
.custom-widget .entry-image-link{position:relative;float:left;width:85px;height:65px;overflow:hidden;margin:0 12px 0 0}
.rtl .custom-widget .entry-image-link{float:right;margin:0 0 0 12px}
.custom-widget .entry-image-link .entry-thumb{width:85px;height:65px}
.custom-widget .cmm-avatar{width:55px;height:55px;margin:0 12px 0 0;border-radius:50%}
.custom-widget .cmm-avatar .entry-thumb{border-radius:50%;width:55px;height:55px}
.custom-widget .cmm-snippet{display:block;font-size:12px;line-height:1.4em;margin:0}
.custom-widget .entry-header{overflow:hidden}
.custom-widget .entry-title{font-size:14px;font-weight:600;line-height:1.3em;margin:0 0 3px}
.PopularPosts .popular-post{display:block;overflow:hidden;margin:25px 0 0}
.PopularPosts .popular-post.item-0{margin:0}
.PopularPosts .entry-image-link{position:relative;float:left;width:85px;height:65px;overflow:hidden;z-index:1;margin:0 12px 0 0}
.rtl .PopularPosts .entry-image-link{float:right;margin:0 0 0 12px}
.PopularPosts .entry-image-link .entry-thumb{width:85px;height:65px}
.PopularPosts .entry-header{overflow:hidden}
.PopularPosts .entry-title{font-size:14px;font-weight:600;line-height:1.3em;margin:0 0 3px}
.FeaturedPost .entry-image-link{position:relative;float:left;width:100%;height:180px;z-index:1;overflow:hidden;margin:0}
.FeaturedPost .entry-header{float:left;margin:0}
.FeaturedPost .entry-title{font-size:19px;font-weight:600;line-height:1.3em;margin:10px 0 7px}
.FollowByEmail .widget-content{position:relative;background-color:rgba(155,155,155,0.1);box-sizing:border-box;padding:0}
.FollowByEmail .widget-content-inner{padding:20px}
.follow-by-email-content{position:relative;z-index:5}
.follow-by-email-title{font-size:18px;color:$(title.color);margin:0 0 13px}
.follow-by-email-text{font-size:13px;color:$(meta.color);line-height:1.5em;margin:0 0 15px}
.follow-by-email-address{width:100%;height:34px;background-color:#fff;font-family:inherit;font-size:12px;color:#333;box-sizing:border-box;padding:0 10px;margin:0 0 10px;border:1px solid rgba(155,155,155,0.15);border-radius:0}
.follow-by-email-address:focus{border-color:rgba(155,155,155,0.4)}
.follow-by-email-submit{width:100%;height:34px;background-color:$(button.bg);font-family:inherit;font-size:12px;color:$(button.color);font-weight:400;text-transform:uppercase;line-height:34px;cursor:pointer;padding:0 20px;border:0;border-radius:0}
.follow-by-email-submit:hover{background-color:$(button.hover.bg);color:$(button.hover.color)}
.list-label li,.archive-list li{position:relative;display:block}
.list-label li a,.archive-list li a{display:block;color:$(title.color);font-size:13px;font-weight:400;text-transform:capitalize;padding:5px 0}
.list-label li:first-child a,.archive-list li:first-child a{padding:0 0 5px}
.list-label li:last-child a,.archive-list li:last-child a{padding-bottom:0}
.list-label li a:hover,.archive-list li a:hover{color:$(title.hover.color)}
.list-label .label-count,.archive-list .archive-count{float:right;color:$(meta.color);text-decoration:none;margin:1px 0 0 5px}
.rtl .list-label .label-count,.rtl .archive-list .archive-count{float:left;margin:1px 5px 0 0}
.cloud-label li{position:relative;float:left;margin:0 5px 5px 0}
.rtl .cloud-label li{float:right;margin:0 0 5px 5px}
.cloud-label li a{display:block;height:26px;background-color:rgba(155,155,155,0.1);color:$(meta.color);font-size:12px;line-height:26px;font-weight:400;padding:0 10px;border-radius:0}
.cloud-label li a:hover{background-color:$(button.hover.bg);color:$(button.hover.color)}
.cloud-label .label-count{display:none}
.BlogSearch .search-form{display:flex;background-color:rgba(255,255,255,0.05);padding:2px;border:1px solid rgba(155,155,155,0.15);border-radius:0}
.BlogSearch .search-input{float:left;width:100%;height:32px;background-color:rgba(0,0,0,0);font-family:inherit;font-weight:400;font-size:13px;color:$(body.text.color);line-height:32px;box-sizing:border-box;padding:0 10px;margin:0;border:0}
.BlogSearch .search-input:focus{outline:none}
.BlogSearch .search-action{float:right;width:auto;height:32px;font-family:inherit;font-size:12px;font-weight:400;line-height:32px;text-transform:uppercase;cursor:pointer;box-sizing:border-box;background-color:$(button.bg);color:$(button.color);padding:0 15px;border:0;border-radius:0}
.BlogSearch .search-action:hover{background-color:$(button.hover.bg);color:$(button.hover.color)}
.Profile ul li{float:left;width:100%;margin:20px 0 0}
.Profile ul li:first-child{margin:0}
.Profile .profile-img{float:left;width:55px;height:55px;background-color:rgba(155,155,155,0.08);overflow:hidden;color:transparent!important;margin:0 12px 0 0;border-radius:50%}
.Profile .profile-datablock{margin:0}
.Profile .profile-info > .profile-link{display:inline-block;font-size:12px;color:$(body.link.color);font-weight:400;margin:3px 0 0}
.Profile .profile-info > .profile-link:hover{color:$(title.color)}
.Profile .g-profile,.Profile .profile-data .g-profile{font-size:15px;color:$(title.color);font-weight:700;line-height:1.4em;margin:0 0 5px}
.Profile .g-profile:hover,.Profile .profile-data .g-profile:hover{color:$(title.hover.color)}
.Profile .profile-textblock{display:none}
.profile-data.location{font-size:12px;color:$(meta.color);line-height:1.4em;margin:2px 0 0}
.ophelia-pro-widget-ready .PageList ul li,.ophelia-pro-widget-ready .LinkList ul li{position:relative;display:block}
.ophelia-pro-widget-ready .PageList ul li a,.ophelia-pro-widget-ready .LinkList ul li a{display:block;color:$(title.color);font-size:13px;font-weight:400;padding:5px 0}
.ophelia-pro-widget-ready .PageList ul li:first-child a,.ophelia-pro-widget-ready .LinkList ul li:first-child a{padding:0 0 5px}
.ophelia-pro-widget-ready .PageList ul li a:hover,.ophelia-pro-widget-ready .LinkList ul li a:hover{color:$(title.hover.color)}
.Text .widget-content{font-family:var(--text-font);font-size:13px;line-height:1.5em}
.Image.about-image > .widget-title{display:none}
.Image .image-caption{font-size:13px;line-height:1.6em;margin:10px 0 0;display:block}
.Image.about-image .image-caption{margin:15px 0 0}
.contact-form-widget form{font-family:inherit;font-weight:400}
.contact-form-name{float:left;width:100%;height:34px;background-color:rgba(255,255,255,0.05);font-family:inherit;font-size:13px;color:$(body.text.color);line-height:34px;box-sizing:border-box;padding:5px 10px;margin:0 0 10px;border:1px solid rgba(155,155,155,0.15);border-radius:0}
.contact-form-email{float:left;width:100%;height:34px;background-color:rgba(255,255,255,0.05);font-family:inherit;font-size:13px;color:$(body.text.color);line-height:34px;box-sizing:border-box;padding:5px 10px;margin:0 0 10px;border:1px solid rgba(155,155,155,0.15);border-radius:0}
.contact-form-email-message{float:left;width:100%;background-color:rgba(255,255,255,0.05);font-family:inherit;font-size:13px;color:$(body.text.color);box-sizing:border-box;padding:5px 10px;margin:0 0 10px;border:1px solid rgba(155,155,155,0.15);border-radius:0}
.contact-form-button-submit{float:left;width:100%;height:34px;background-color:$(button.bg);font-family:inherit;font-size:12px;color:$(button.color);font-weight:400;text-transform:uppercase;line-height:34px;cursor:pointer;box-sizing:border-box;padding:0 10px;margin:0;border:0;border-radius:0}
.contact-form-button-submit:hover{background-color:$(button.hover.bg);color:$(button.hover.color)}
.contact-form-error-message-with-border{float:left;width:100%;background-color:rgba(0,0,0,0);font-size:12px;color:#e74c3c;text-align:left;line-height:12px;padding:3px 0;margin:10px 0;box-sizing:border-box;border:0}
.contact-form-success-message-with-border{float:left;width:100%;background-color:rgba(0,0,0,0);font-size:12px;color:#27ae60;text-align:left;line-height:12px;padding:3px 0;margin:10px 0;box-sizing:border-box;border:0}
.rtl .contact-form-error-message-with-border,.rtl .contact-form-success-message-with-border{text-align:right}
.contact-form-cross{cursor:pointer;margin:0 0 0 3px}
.rtl .contact-form-cross{margin:0 3px 0 0}
.contact-form-error-message,.contact-form-success-message{margin:0}
.contact-form-name:focus,.contact-form-email:focus,.contact-form-email-message:focus{background-color:rgba(155,155,155,0.05);border-color:rgba(155,155,155,0.4)}
#footer-wrapper{background-color:$(footer.bg);color:$(footer.text.color);border-top:1px solid rgba(155,155,155,0.15)}
#footer-wrapper > .container{position:relative;overflow:hidden;margin:0 auto}
.footer-widgets-wrap{position:relative;display:flex;margin:0 -20px}
#footer-wrapper .footer{display:inline-block;float:left;width:calc(100% / 3);box-sizing:border-box;padding:50px 20px}
.rtl #footer-wrapper .footer{float:right}
#footer-wrapper .footer.no-items{padding:0 20px}
#footer-wrapper .footer .widget{float:left;width:100%;padding:0;margin:35px 0 0}
#footer-wrapper .footer .widget:first-child{margin:0}
.footer .widget > .widget-title > h3,.footer .follow-by-email-title{position:relative;color:$(footer.widget.title.color);font-size:21px;font-weight:400;margin:0 0 25px}
.footer .follow-by-email-title{margin:0 0 13px}
.footer .about-text > .widget-title{display:none}
.footer .loader{height:145px}
.footer .no-posts{color:$(footer.text.color)}
.footer .PopularPosts .widget-content .post:first-child,.footer .custom-widget li:first-child,.footer .cmm-widget li:first-child{padding:0}
.footer .entry-title a,.footer .LinkList ul li a,.footer .PageList ul li a,.footer .Profile .g-profile,.footer .Profile .profile-data .g-profile{color:$(footer.color)}
.footer .entry-title a:hover{color:$(footer.post.title.hover.color)}
.footer .Profile .profile-info > .profile-link{color:$(footer.hover.color)}
.footer .Profile .profile-info > .profile-link:hover{color:$(footer.color)}
.footer .LinkList ul li a:hover,.footer .PageList ul li a:hover,.footer .Profile .g-profile:hover,.footer .Profile .profile-data .g-profile:hover{color:$(footer.hover.color)}
.footer .custom-widget .cmm-snippet,.footer .profile-data.location,.footer .Text .widget-content,.footer .Image .image-caption{color:$(footer.text.color)}
.footer .list-label li a,.footer .archive-list li a,.footer .PageList ul li a,.footer .LinkList ul li a{border-color:rgba(155,155,155,0.06)}
.footer .list-label li a,.footer .list-label li a:before,.footer .archive-list li a,.footer .archive-list li a:before{color:$(footer.color)}
.footer .list-label li > a:hover,.footer .archive-list li > a:hover,.footer .Text .widget-content a{color:$(footer.hover.color)}
.footer .cloud-label li a{color:$(footer.color)}
.footer .cloud-label li a:hover{background-color:$(button.bg);color:$(button.color)}
.footer .contact-form-name,.footer .contact-form-email,.footer .contact-form-email-message,.footer .BlogSearch .search-input{color:$(footer.color)}
#sub-footer-wrapper{display:block;width:100%;height:60px;color:$(footer.color);line-height:60px;overflow:hidden;border-top:1px solid rgba(155,155,155,0.15)}
#sub-footer-wrapper .container{margin:0 auto;overflow:hidden}
#footer-menu{float:right;position:relative;display:block}
.rtl #footer-menu{float:left}
#footer-menu .widget > .widget-title,#footer-copyright .widget > .widget-title{display:none}
#footer-menu ul li{float:left;display:inline-block;height:30px;padding:0;margin:0}
.rtl #footer-menu ul li{float:right}
#footer-menu ul li a{display:block;font-size:11px;color:$(footer.color);font-weight:500;text-transform:uppercase;padding:0;margin:0 0 0 30px}
.rtl #footer-menu ul li a{margin:0 30px 0 0}
#footer-menu ul li a:hover{color:$(footer.hover.color)}
#sub-footer-wrapper .footer-copyright{float:left;font-size:11px;font-weight:500;text-align:center;text-transform:uppercase;margin:0}
.rtl #sub-footer-wrapper .footer-copyright{float:right}
#sub-footer-wrapper .footer-copyright a{color:$(footer.color)}
#sub-footer-wrapper .footer-copyright a:hover{color:$(footer.hover.color)}
.hidden-widgets{display:none;visibility:hidden}
.back-top{display:none;position:fixed;bottom:15px;right:15px;width:32px;height:32px;background-color:$(button.bg);cursor:pointer;overflow:hidden;font-size:13px;color:$(button.color);text-align:center;line-height:32px;z-index:2;margin:0}
.rtl .back-top{right:auto;left:15px}
.back-top:after{content:'\f077';position:relative;font-family:'Font Awesome 5 Free';font-weight:900}
.back-top:hover{background-color:$(button.hover.bg);color:$(button.hover.color);box-shadow:0 0 5px rgba(0,0,0,0.15)}
.error404 #main-wrapper{width:100%}
.error404 #sidebar-wrapper{display:none}
.errorWrap{color:$(title.color);text-align:center;padding:60px 0}
.errorWrap h3{font-size:160px;line-height:1em;margin:0 0 40px}
.errorWrap h4{font-size:25px;margin:0 0 30px}
.errorWrap p{margin:0 0 10px}
.errorWrap a{display:inline-block;height:32px;background-color:$(button.bg);font-size:15px;color:$(button.color);font-weight:400;line-height:32px;padding:0 30px;margin:15px 0 0;border-radius:0}
.errorWrap a:hover{background-color:$(button.hover.bg);color:$(button.hover.color)}
.cookie-choices-info{top:auto!important;bottom:0}
@media screen and (max-width: 1133px) {
#outer-wrapper{max-width:100%}
.row-x1{width:100%}
.navbar .container,.headerify .container,#slider-wrapper .container,#content-wrapper > .container,#footer-wrapper .container{box-sizing:border-box;padding:0 20px}
}
@media screen and (max-width: 980px) {
#main-wrapper{width:calc(100% - (30% + 35px))}
#sidebar-wrapper{width:30%}
}
@media screen and (max-width: 880px) {
.nav-active .back-top{opacity:0!important}
#outer-wrapper{transition:filter .17s ease}
.navbar .container{padding:0}
.overlay,.show-mobile-menu,#slide-menu{display:block}
.nav-active .overlay{visibility:visible;opacity:1}
.social-wrap{right:60px}
.show-search,.hide-search{width:auto;text-align:center;padding:0 20px}
#nav-search .search-input{padding:0 60px 0 20px}
.rtl #nav-search .search-input{padding:0 20px 0 60px}
.main-menu,.ophelia-pro-main-menu{display:none}
#main-wrapper,#sidebar-wrapper{width:100%}
#sidebar-wrapper{margin:50px 0 0}
.footer-widgets-wrap{display:block;overflow:hidden;padding:35px 0 0}
.compact-footer .footer-widgets-wrap{padding:0}
#footer-wrapper .footer{width:100%;padding:0 20px 35px}
#footer-wrapper .footer.no-items{padding:0 20px}
}
@media screen and (max-width: 680px) {
.index-post .entry-image,.rtl .index-post .entry-image{width:100%;margin:0 0 15px}
.index-post .entry-header,.index-post .entry-content{float:left;width:100%}
.related-posts .related-item{width:50%;padding:0 10px;margin:25px 0 0}
.related-posts .related-item.item-2{margin:25px 0 0}
.related-posts.total-3 .related-item{width:100%;padding:0 10px}
.related-posts.total-3 .related-item.item-1{margin:20px 0 0}
.related-posts.total-3 .entry-image-link{height:170px}
.related-posts.total-3 .entry-title{font-size:19px;margin:10px 0 5px}
#sub-footer-wrapper{height:auto;line-height:1.4em;padding:20px 0}
#footer-menu,#sub-footer-wrapper .footer-copyright{width:100%;height:auto;line-height:inherit;text-align:center}
#footer-menu ul li,.rtl #footer-menu ul li{float:none;height:auto}
#footer-menu ul li a,.rtl #footer-menu ul li a{line-height:inherit;margin:0 10px}
#sub-footer-wrapper .footer-copyright{padding:0 0 15px}
}
@media screen and (max-width: 540px) {
.related-posts .entry-image-link{height:120px}
}
@media screen and (max-width: 440px) {
#main-slider .show-ify .widget-content,.beauty-slider .slider-item{height:250px}
.beauty-slider .entry-info{padding:15px}
.beauty-slider .entry-title{font-size:19px}
.index-post .entry-image{height:180px}
.item-post h1.entry-title{font-size:26px}
.post-share{margin:25px 0 0}
.share-links li{margin:5px 5px 0 0}
.share-links li a.twitter{width:34px}
.share-links li a.twitter span{display:none}
.share-links li a.twitter:before{width:34px;background-color:rgba(0,0,0,0)}
.about-author .avatar-container{width:55px;height:55px;margin:0 15px 0 0}
}
@media screen and (max-width: 360px) {
#slide-menu{width:270px}
.main-logo{padding:20px 0}
.main-logo h1{font-size:30px}
.social-wrap{display:none}
.index-post .entry-image{height:170px}
.related-posts .entry-image-link{height:100px}
.item-post h1.entry-title{font-size:23px}
.about-author .author-name span{display:none}
.share-links li a,.share-links li a.twitter{width:32px}
.share-links li a.twitter:before{width:32px;background-color:rgba(0,0,0,0)}
.errorWrap h3{font-size:130px}
}
.svg-icon-24 {
     width: 24px;
     height: 24px;
   }

b:if.b:template-skin:
/*------Layout (No Edit)----------*/
body#layout #outer-wrapper,body#layout .row{width:auto;padding:0}
body#layout{width:920px;position:relative;background-color:#f9f9f9;padding:95px 5px 0;margin:0}
body#layout:before{content:'Ophelia - v1.4.0';position:absolute;top:0;left:5px;right:5px;height:95px;font-family:Roboto,sans-serif;font-size:23px;color:#1f2024;line-height:95px;text-align:center}
body#layout div.section{display:block;background-color:#f1f1f1!important;margin:0 5px 10px!important;padding:16px 16px 18px!important;border-color:#e5e5e5}
body#layout .no-items.section{display:block}
body#layout .section h4{font-size:14px;color:#1f2024;text-transform:uppercase;margin:0}
body#layout .section h4:after{text-transform:initial;color:#656565;font-weight:400}
body#layout .add_widget a{color:#0084b4!important}
body#layout .widget-wrap3{overflow:hidden}
body#layout .widget-content{width:auto;max-width:none;max-height:none;margin:0;border:1px solid #e5e5e5;border-left:0}
body#layout .locked-widget .widget-content{border-left:1px solid #0084b4}
body#layout .locked-widget .widget-content:hover{border-left-color:#79b530}
body#layout .widget .widget-content a.editlink{border-radius:2px}
body#layout .visibility .editlink{background:#0084b4 url(https://1.bp.blogspot.com/-iQoCOwqjB-w/Wy1bDznOM4I/AAAAAAAACGA/8BUOPStr0sk5oud9hWpHBQTrmkeJDoAvACK4BGAYYCw/s18-c/mode_edit_w600_24dp.png) no-repeat center!important}
body#layout .visibility .editlink:hover{background-color:#79b530!important}
body#layout .draggable-widget .widget-wrap2{background:#0084b4 url(https://1.bp.blogspot.com/-yTAuT5aZ1EY/Wy1eEeo4SbI/AAAAAAAACGM/FxOTPwL-Ch0_lyZxLRzhv2EWHINOmCjWACK4BGAYYCw/s22/draggable.png) no-repeat 4px 50%!important}
body#layout .draggable-widget .widget-wrap1:hover .widget-wrap2{background-color:#79b530!important}
body#layout .visibility .layout-widget-state.visible{background-image:url(https://4.bp.blogspot.com/-cgTj6sYN20w/XG1MixYFa3I/AAAAAAAAD94/1Q79bEtkdMc6se8dvKvseNL-cedMPz3JQCK4BGAYYCw/s1600/visibility_c3_600_24dp.png)!important}
body#layout .visibility .layout-widget-state.not-visible{background-image:url(https://4.bp.blogspot.com/-xCIqf_dm-jE/XG1MsEOgHYI/AAAAAAAAD-A/hpgoQ1p4kGwjvbi37Z1a5eGItNKRxkh1QCK4BGAYYCw/s1600/visibility_off_c3_600_24dp.png)!important;opacity:1}
body#layout div.layout-widget-description{font-size:11px;line-height:1.2em}
body#layout .theme-options,body#layout #ophelia-pro-main-menu .widget{display:block!important}
body#layout div.ify-panel{background-color:#edf4ff!important;overflow:hidden!important;border-color:#cdd4ef}
body#layout .ify-panel .widget{float:left;width:32%;margin-right:2%}
body#layout .ify-panel .widget-content{border-color:#cdd4ef!important}
body#layout .ify-panel #LinkList151{margin-right:0}
body#layout .ify-panel div.layout-widget-description{display:none}
body#layout .navbar > .container{display:block;padding:0}
body#layout .menu-wrap,body#layout .social-wrap{position:relative;float:left;width:50%;margin:0}
body#layout .headerify{float:left;width:100%}
body#layout .show-mobile-menu,body#layout .show-search,body#layout #nav-search{display:none}
body#layout #content-wrapper{margin:0}
body#layout #content-wrapper > .container{display:flex;margin:0}
body#layout #main-wrapper{width:67%;padding:0}
body#layout #sidebar-wrapper{width:33%;padding:0}
body#layout #custom-ads{display:block!important;display:flex!important}
body#layout #custom-ads .section{width:50%}
body#layout #ify-panel > h4:after{content:' - By Templateify'}
body#layout .section > h4:after{font-size:12px}
body#layout #main-logo > h4:after{content:' - Site Logo (Standard height = 100px)'}
body#layout #ophelia-pro-main-menu > h4:after{content:' - DropDown and MegaMenu'}
body#layout #main-social > h4:after{content:' - on Main Menu and Mobile Menu'}
body#layout #main-slider > h4:after{content:' - Work With Label or Most Recent'}
body#layout #home-ad > h4:after{content:' - Before Blog Posts on HomePage'}
body#layout #main > h4:after{content:' - Default Blog Posts Section'}
body#layout #main-before-ad > h4:after{content:' - Before Post Content on PostPage'}
body#layout #main-after-ad > h4:after{content:' - After Post Content on PostPage'}
body#layout .sidebar > h4:after{content:' - Default Gadgets'}
body#layout #footer-sec1 > h4:after{content:' - Left Section'}
body#layout #footer-sec2 > h4:after{content:' - Center Section'}
body#layout #footer-sec3 > h4:after{content:' - Right Section'}
body#layout #footer-copyright > h4:after{content:' - Custom Footer Credits'}
body#layout #footer-menu > h4:after{content:' - Footer Links'}
body#layout .footer-widgets-wrap{display:flex}
body#layout .footer-widgets-wrap div.footer{width:100%}
body#layout #sub-footer-wrapper .container{display:flex}
body#layout #footer-menu,body#layout #footer-copyright{width:50%}
body#layout:after{content:'Design by Templateify.com';display:block;font-family:Roboto,sans-serif;font-size:14px;color:#555;line-height:1;text-align:center;visibility:visible;padding:20px 0}
/*------Layout (end)----------*/

